DROP TRIGGER IF EXISTS [dbo].[Group_AfterInsert] GO CREATE TRIGGER [dbo].[Group_AfterInsert] ON [dbo].[Group] AFTER INSERT AS SET NOCOUNT ON; INSERT INTO [queue].[Task] ([Action], [Custom], [Object], [ObjectID]) select 'Add', [queue].WriteIndexXml('', 'Group', ID, coalesce(UpdatedBy, 0)), 'Group', ID from inserted;
INSERT INTO [dbo].[Asset] ([AssetTypeID],[State],SourceID,[Object],[ObjectID],[CreatedOn],[CreatedBy],[UpdatedOn],[UpdatedBy]) SELECT T.ID, 1, O.ID, 'Group', O.ID, O.UpdatedOn, coalesce(O.UpdatedBy, 0), O.UpdatedOn, coalesce(O.UpdatedBy, 0) FROM inserted O inner join AssetType T on T.Object = 'GroupType' and T.ObjectID = 1; GO DROP TRIGGER IF EXISTS [dbo].[Group_AfterUpdate] GO CREATE TRIGGER [dbo].[Group_AfterUpdate] ON [dbo].[Group] AFTER UPDATE AS SET NOCOUNT ON; INSERT INTO [queue].[Task] ([Action], [Custom], [Object], [ObjectID]) select 'Update', [queue].WriteIndexXml('', 'Group', ID, coalesce(UpdatedBy, 0)), 'Group', ID from inserted;
update T set T.UpdatedBy = S.UpdatedBy, T.UpdatedOn = S.UpdatedOn from Asset T inner join inserted S on T.Object = 'Group' and T.ObjectID = S.ID; GO
